<template><PlayerPageShell title="我的" subtitle="竞赛选手独立登录态"><view class="card"><text>登录账号：{{ profile.maskedMobile || '--' }}</text><text>选手编号：{{ profile.playerId || '--' }}</text><text>身份状态：{{ profile.status === 'active' ? '已激活' : profile.status || '--' }}</text><text>可访问赛事：{{ profile.events?.length || 0 }} 场</text></view><button class="logout" @click="logout">退出登录</button></PlayerPageShell></template>
<script>import{getCurrentPlayer,playerLogout}from'@/api/competition-player';import PlayerPageShell from './components/PlayerPageShell.vue';import{guardCompetitionPlayerRoute}from'@/utils/competition-route-guard';import{useCompetitionPlayerStore}from'@/store/competitionPlayer';export default{components:{PlayerPageShell},data:()=>({profile:{}}),async onShow(){if(!guardCompetitionPlayerRoute())return;try{this.profile=await getCurrentPlayer();useCompetitionPlayerStore().setProfile(this.profile)}catch(e){uni.showToast({title:e.message||'资料加载失败',icon:'none'})}},methods:{async logout(){try{await playerLogout()}catch(e){}useCompetitionPlayerStore().clearSession();uni.reLaunch({url:'/pages/competition-app/entry'})}}}</script>
<style scoped>.card{display:flex;flex-direction:column;gap:20rpx;padding:32rpx;background:#fff;border-radius:20rpx;font-size:28rpx;line-height:1.5}.logout{margin-top:32rpx;color:#d84e4e;background:#fff;border:1rpx solid #f3baba;border-radius:16rpx}</style>
